/* ---- modules/theme.js ---- */
/* Theme toggle (dark and light), remembered between visits. */
(function (App) {
  'use strict';

  var DARK_COLOR = '#0B1A24';
  var LIGHT_COLOR = '#F3F6F8';

  function init() {
    var root = document.documentElement;
    var button = document.getElementById('theme');
    var meta = document.querySelector('meta[name="theme-color"]');
    if (!button) return;

    function apply(theme) {
      root.setAttribute('data-theme', theme);
      if (meta) meta.setAttribute('content', theme === 'light' ? LIGHT_COLOR : DARK_COLOR);
      button.setAttribute('aria-label', theme === 'light' ? button.dataset.labelDark : button.dataset.labelLight);
    }

    apply(root.getAttribute('data-theme') === 'light' ? 'light' : 'dark');

    button.addEventListener('click', function () {
      var next = root.getAttribute('data-theme') === 'light' ? 'dark' : 'light';
      apply(next);
      try { localStorage.setItem('theme', next); } catch (err) { /* storage can be blocked */ }
    });
  }

  App.theme = { init: init };
})(window.App = window.App || {});

/* ---- modules/reveal.js ---- */
/* Count the key numbers up and fill the language meters, once, when they scroll into view. */
(function (App) {
  'use strict';

  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var COUNT_DURATION = 1300;

  function countUp(el, formatter) {
    var end = Number(el.dataset.count);
    var suffix = el.dataset.suffix || '';
    if (reduceMotion) {
      el.textContent = formatter.format(end) + suffix;
      return;
    }
    var start = performance.now();
    (function tick(now) {
      var t = Math.min((now - start) / COUNT_DURATION, 1);
      var eased = 1 - Math.pow(1 - t, 3);
      el.textContent = formatter.format(Math.round(end * eased)) + (t === 1 ? suffix : '');
      if (t < 1) requestAnimationFrame(tick);
    })(start);
  }

  function observeOnce(targets, threshold, callback) {
    var observer = new IntersectionObserver(function (entries, obs) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        callback(entry.target);
        obs.unobserve(entry.target);
      });
    }, { threshold: threshold });
    targets.forEach(function (target) { observer.observe(target); });
  }

  function init() {
    // Stop the SVG packets for people who prefer less motion.
    if (reduceMotion) {
      document.querySelectorAll('.pkt').forEach(function (el) { el.remove(); });
    }
    if (!('IntersectionObserver' in window)) return;

    var formatter = new Intl.NumberFormat('en-US');
    var numbers = document.querySelector('.numbers');
    if (numbers) {
      observeOnce([numbers], 0.4, function (section) {
        section.querySelectorAll('[data-count]').forEach(function (el) { countUp(el, formatter); });
      });
    }

    var meters = Array.prototype.slice.call(document.querySelectorAll('.meter'));
    meters.forEach(function (meter) { meter.classList.add('ready'); });
    observeOnce(meters, 0.6, function (meter) { meter.classList.add('in'); });
  }

  App.reveal = { init: init };
})(window.App = window.App || {});

/* ---- modules/roles.js ---- */
/* Role picker. Content comes from the JSON block the build script writes into the page. */
(function (App) {
  'use strict';

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function list(tag, className, items, itemTag) {
    var parent = el(tag, className);
    items.forEach(function (text) { parent.appendChild(el(itemTag, '', text)); });
    return parent;
  }

  function renderPanel(role, labels) {
    var fragment = document.createDocumentFragment();
    fragment.appendChild(el('h3', '', role.title));
    fragment.appendChild(el('p', 'sum', role.sum));
    fragment.appendChild(el('h4', '', labels.tools));
    fragment.appendChild(list('div', 'tags', role.tags, 'span'));
    fragment.appendChild(el('h4', '', labels.proof_title));
    fragment.appendChild(list('ul', 'proof', role.proof, 'li'));
    if (role.note) fragment.appendChild(el('p', 'note', role.note));

    var download = el('p', 'dl');
    var link = el('a', 'btn primary', labels.download);
    link.href = role.href;
    link.setAttribute('download', '');
    download.appendChild(link);
    fragment.appendChild(download);
    return fragment;
  }

  function init() {
    var dataNode = document.getElementById('roles-data');
    var panel = document.getElementById('panel');
    if (!dataNode || !panel) return;

    var data = JSON.parse(dataNode.textContent);
    var tabs = Array.prototype.slice.call(document.querySelectorAll('[role="tab"]'));

    function show(id) {
      var role = data.roles[id];
      if (!role) return;
      panel.replaceChildren(renderPanel(role, data.labels));
      panel.setAttribute('aria-labelledby', 't-' + id);
      panel.classList.remove('swap');
      void panel.offsetWidth; // restart the CSS animation
      panel.classList.add('swap');
      tabs.forEach(function (tab) {
        tab.setAttribute('aria-selected', String(tab.dataset.role === id));
      });
    }

    // Arrow keys follow reading direction, so they are swapped in right-to-left pages.
    var rtl = document.documentElement.dir === 'rtl';
    var KEY_STEP = { ArrowDown: 1, ArrowUp: -1, ArrowRight: rtl ? -1 : 1, ArrowLeft: rtl ? 1 : -1 };

    tabs.forEach(function (tab, index) {
      tab.addEventListener('click', function () { show(tab.dataset.role); });
      tab.addEventListener('keydown', function (event) {
        var step = KEY_STEP[event.key];
        if (!step) return;
        event.preventDefault();
        var next = tabs[(index + step + tabs.length) % tabs.length];
        next.focus();
        show(next.dataset.role);
      });
    });

    show(tabs.length ? tabs[0].dataset.role : Object.keys(data.roles)[0]);
  }

  App.roles = { init: init };
})(window.App = window.App || {});

/* ---- modules/filter.js ---- */
/* Project filter chips. */
(function (App) {
  'use strict';

  function init() {
    var chips = Array.prototype.slice.call(document.querySelectorAll('.chip'));
    var items = Array.prototype.slice.call(document.querySelectorAll('#rows li'));

    function select(chip) {
      var filter = chip.dataset.filter;
      chips.forEach(function (other) {
        var on = other === chip;
        other.classList.toggle('on', on);
        other.setAttribute('aria-pressed', String(on));
      });
      items.forEach(function (item) {
        item.hidden = !(filter === 'all' || item.dataset.tags.split(' ').indexOf(filter) > -1);
      });
    }

    chips.forEach(function (chip) {
      chip.addEventListener('click', function () { select(chip); });
    });
  }

  App.filter = { init: init };
})(window.App = window.App || {});

/* ---- modules/analytics.js ---- */
/* Optional visit counts with GoatCounter: no cookies, no personal data.
   Turn it on by writing the site code in assets/config.js. */
(function (App) {
  'use strict';

  function init() {
    var config = window.PORTFOLIO_CONFIG || {};
    if (!config.goatcounterCode) return;

    var script = document.createElement('script');
    script.async = true;
    script.src = 'https://gc.zgo.at/count.js';
    script.setAttribute('data-goatcounter', 'https://' + config.goatcounterCode + '.goatcounter.com/count');
    document.head.appendChild(script);

    var note = document.getElementById('privacy-note');
    if (note) note.hidden = false;

    // Count CV downloads as an event: only which file, nothing about the visitor.
    document.addEventListener('click', function (event) {
      var link = event.target.closest ? event.target.closest('a[download]') : null;
      var href = link && link.getAttribute('href');
      if (!href || !/\.pdf$/i.test(href)) return;
      var name = href.split('/').pop().replace(/\.pdf$/i, '');
      try {
        if (window.goatcounter && window.goatcounter.count) {
          window.goatcounter.count({ path: 'cv-download/' + name, title: 'CV download: ' + name, event: true });
        }
      } catch (err) { /* counting must never break the page */ }
    });
  }

  App.analytics = { init: init };
})(window.App = window.App || {});

/* ---- main.js ---- */
/* Entry point: start each module once the DOM is ready. */
(function (App) {
  'use strict';

  function start() {
    ['theme', 'reveal', 'roles', 'filter', 'analytics'].forEach(function (name) {
      try { App[name].init(); } catch (err) { console.error('Module "' + name + '" failed to start', err); }
    });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})(window.App = window.App || {});
